import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline';
  fullWidth?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  fullWidth = false, 
  className = '', 
  ...props 
}) => {
  const baseStyles = "px-6 py-4 rounded-xl font-bold transition-all duration-200 flex items-center justify-center gap-2 text-lg shadow-md hover:shadow-lg active:scale-95";

  const variants = {
    primary: "bg-green-600 hover:bg-green-700 text-white border-2 border-transparent",
    secondary: "bg-gray-800 hover:bg-gray-900 text-white border-2 border-transparent",
    outline: "bg-white hover:bg-gray-50 text-gray-800 border-2 border-gray-200"
  };

  const widthClass = fullWidth ? 'w-full' : '';

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${widthClass} ${className}`}
      {...props}
    >
      {children}
    </button>
  );
};

import React from 'react';
import { QuizStepConfig } from '../types';
import { Button } from './Button';

interface QuizStepProps {
  step: QuizStepConfig;
  onAnswer: (value: string | string[]) => void;
  selectedValues: string[];
}

export const QuizStep: React.FC<QuizStepProps> = ({ step, onAnswer, selectedValues }) => {
  const handleOptionClick = (value: string) => {
    if (step.multiSelect) {
      const newValues = selectedValues.includes(value)
        ? selectedValues.filter(v => v !== value)
        : [...selectedValues, value];
      onAnswer(newValues);
    } else {
      onAnswer(value);
    }
  };

  const handleNext = () => {
    // For multiselect or interstitials
    onAnswer(selectedValues);
  };

  if (step.type === 'INTRO') {
     return (
        <div className="flex flex-col items-center justify-center min-h-[60vh] text-center space-y-8 animate-fade-in">
          <h1 className="text-3xl md:text-4xl font-extrabold text-gray-900 leading-tight">
            {step.question}
          </h1>
          <p className="text-xl text-gray-600 max-w-lg">
            {step.description}
          </p>
          <Button onClick={() => onAnswer("start")} fullWidth className="max-w-md animate-pulse">
            COMEÇAR AGORA
          </Button>
        </div>
     )
  }

  if (step.type === 'INTERSTITIAL_IMAGE') {
    return (
      <div className="flex flex-col items-center text-center space-y-6 animate-fade-in">
        <h2 className="text-2xl font-bold text-gray-900">{step.question}</h2>
        {step.description && <p className="text-gray-600">{step.description}</p>}
        {step.imageUrl && (
          <img 
            src={step.imageUrl} 
            alt="Quiz illustration" 
            className="rounded-lg shadow-lg max-w-full h-auto max-h-[300px] object-cover"
          />
        )}
        <Button onClick={handleNext} fullWidth className="max-w-md">
          {step.nextLabel || 'Continuar'}
        </Button>
      </div>
    );
  }

  return (
    <div className="flex flex-col space-y-6 w-full max-w-xl mx-auto animate-fade-in">
      <div className="text-center space-y-2">
        <h2 className="text-2xl font-bold text-gray-900">{step.question}</h2>
        {step.description && <p className="text-gray-600 text-sm">{step.description}</p>}
      </div>

      <div className={`grid gap-3 ${step.options && step.options.length > 4 ? 'grid-cols-1 md:grid-cols-2' : 'grid-cols-1'}`}>
        {step.options?.map((option) => {
          const isSelected = selectedValues.includes(option.value);
          return (
            <button
              key={option.value}
              onClick={() => handleOptionClick(option.value)}
              className={`p-4 rounded-xl border-2 text-left transition-all flex items-center justify-between group
                ${isSelected 
                  ? 'border-green-600 bg-green-50 text-green-900' 
                  : 'border-gray-200 bg-white hover:border-green-300 text-gray-700'
                }`}
            >
              <div className="flex flex-col items-center md:flex-row md:items-center gap-3 w-full">
                {option.icon && <div className="text-gray-500 group-hover:text-green-600">{option.icon}</div>}
                <span className="font-medium text-lg w-full text-center md:text-left">{option.label}</span>
              </div>
              {step.multiSelect && (
                 <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center
                    ${isSelected ? 'bg-green-600 border-green-600' : 'border-gray-300'}
                 `}>
                    {isSelected && <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>}
                 </div>
              )}
            </button>
          );
        })}
      </div>

      {step.multiSelect && (
        <Button onClick={handleNext} disabled={selectedValues.length === 0} fullWidth>
          {step.nextLabel || 'Continuar'}
        </Button>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { TESTIMONIALS_CAROUSEL } from '../constants';

const phrases = [
  "Analisando seu perfil capilar...",
  "Calculando projeção de crescimento...",
  "Selecionando os melhores ingredientes...",
  "Gerando seu plano personalizado..."
];

export const LoadingSequence: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [completedSteps, setCompletedSteps] = useState<number>(0);
  const [testimonialIndex, setTestimonialIndex] = useState(0);

  useEffect(() => {
    // Process bars one by one
    if (completedSteps < phrases.length) {
      const timer = setTimeout(() => {
        setCompletedSteps(prev => prev + 1);
      }, 1500); // 1.5s per bar
      return () => clearTimeout(timer);
    } else {
      const timer = setTimeout(() => {
        onComplete();
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [completedSteps, onComplete]);

  // Carousel auto-rotation
  useEffect(() => {
    const timer = setInterval(() => {
      setTestimonialIndex(prev => (prev + 1) % TESTIMONIALS_CAROUSEL.length);
    }, 3000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="w-full max-w-xl mx-auto space-y-8 py-10">
      <div className="space-y-6">
        {phrases.map((phrase, index) => (
          <div key={index} className="space-y-2">
            <div className="flex justify-between text-sm font-medium text-gray-700">
               <span>{phrase}</span>
               {completedSteps > index && <span className="text-green-600">✓</span>}
            </div>
            <div className="h-3 w-full bg-gray-200 rounded-full overflow-hidden">
               <div 
                 className="h-full bg-green-600 transition-all duration-1000 ease-out"
                 style={{ 
                   width: completedSteps > index ? '100%' : (completedSteps === index ? '100%' : '0%'),
                   transitionDelay: completedSteps === index ? '0ms' : '0ms' 
                  }}
               ></div>
            </div>
          </div>
        ))}
      </div>

      <div className="pt-8 border-t border-gray-100">
         <div className="bg-white p-6 rounded-xl shadow-lg border border-gray-100 text-center animate-fade-in relative overflow-hidden min-h-[140px] flex flex-col justify-center">
            <p className="text-gray-600 italic mb-4">"{TESTIMONIALS_CAROUSEL[testimonialIndex].text}"</p>
            <p className="font-bold text-gray-900">{TESTIMONIALS_CAROUSEL[testimonialIndex].name}</p>
         </div>
      </div>
    </div>
  );
};

